```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

const encode = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');

const decode = (s) => {
  const v = JSON.parse(Buffer.from(s, 'base64url').toString());
  if (!Array.isArray(v) || v.length !== 2) throw new Error('bad cursor');
  return v;
};

router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

  let cursor = [];
  if (req.query.cursor) {
    try {
      cursor = decode(String(req.query.cursor));
    } catch {
      return res.status(400).json({ error: 'invalid cursor' });
    }
  }

  try {
    // created_at::text keeps microseconds; a JS Date would truncate to ms
    // and skip/repeat rows that share a millisecond.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
         ${cursor.length ? 'WHERE (created_at, id) < ($2, $3)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      [limit + 1, ...cursor] // one extra row tells us if there's a next page
    );

    const page = rows.slice(0, limit);
    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: rows.length > limit ? encode(page[page.length - 1]) : null,
    });
  } catch (err) {
    // class 22 = data exception: the cursor decoded but holds a bad timestamp/id
    if (err.code?.startsWith('22')) return res.status(400).json({ error: 'invalid cursor' });
    next(err);
  }
});

module.exports = router;
